function ensurePrinterCard(x){if(printerCardsByKey[x.key])return printerCardsByKey[x.key];let card=document.createElement('article');card.className='card printer-card';card.innerHTML='<iframe class="printer-camera" frameborder="0"></iframe><div class="printer-card-body"><div class="printer-title"><div><h3></h3><small class="identity"></small></div><button class="remove-printer">Retirer</button></div><p class="file hint"></p><div class="printer-stats"><div><small>État</small><b class="pstate">—</b></div><div><small>Couche</small><b class="player">—</b></div><div><small>Progression</small><b class="pprogress">—</b></div></div><button class="camera-button secondary" style="display:none">Afficher la caméra</button></div>';card.querySelector('h3').textContent=x.name||x.model||x.host;card.querySelector('.identity').textContent=(x.model||'Creality')+' · '+x.host+':'+x.port;card.querySelector('.remove-printer').onclick=()=>window.webkit.messageHandlers.layerShot.postMessage({action:'removePrinter',printerKey:x.key});card.querySelector('.camera-button').onclick=()=>{let view=card.querySelector('.printer-camera');if(view.style.display==='block'){view.style.display='none';view.src='about:blank'}else{view.src=view.dataset.url;view.style.display='block'}};printerGrid.appendChild(card);printerCardsByKey[x.key]=card;return card}
function updatePrinterCard(x){let card=ensurePrinterCard(x);card.classList.remove('offline');card.querySelector('.pstate').textContent=x.state||'—';card.querySelector('.player').textContent=x.layer==null?'—':x.totalLayers?x.layer+' / '+x.totalLayers:x.layer;card.querySelector('.pprogress').textContent=x.progress==null?'—':Math.round(x.progress*100)+' %';card.querySelector('.file').textContent=x.file||'';if(x.camera)setPrinterCamera({key:x.key,url:x.camera})}
function setPrinterCamera(x){let card=printerCardsByKey[x.key];if(!card)return;let img=card.querySelector('.printer-camera');img.dataset.url=x.url;card.querySelector('.camera-button').style.display='inline-block'}
